IF EXISTS(SELECT 1 FROM information_schema.table_privileges WHERE table_schema=DATABASE() AND grantee=CONCAT(CHAR(39),'{{RUNTIME_ROLE}}',CHAR(39),'@',CHAR(39),'%',CHAR(39)) AND privilege_type<>'SELECT') OR EXISTS(SELECT 1 FROM information_schema.schema_privileges WHERE table_schema=DATABASE() AND grantee=CONCAT(CHAR(39),'{{RUNTIME_ROLE}}',CHAR(39),'@',CHAR(39),'%',CHAR(39))) OR EXISTS(SELECT 1 FROM information_schema.column_privileges WHERE table_schema=DATABASE() AND grantee=CONCAT(CHAR(39),'{{RUNTIME_ROLE}}',CHAR(39),'@',CHAR(39),'%',CHAR(39))) OR EXISTS(SELECT 1 FROM mysql.procs_priv WHERE Db=DATABASE() AND User='{{RUNTIME_ROLE}}' AND Routine_name='sp_append_audit') THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='validation:excess_runtime_privilege'; END IF;
IF NOT EXISTS(SELECT 1 FROM mysql.role_edges WHERE FROM_USER='{{RUNTIME_ROLE}}' AND TO_USER='{{APP_USER}}' AND TO_HOST='{{APP_HOST}}') THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='validation:role_grant'; END IF;
END$$
DELIMITER ;
CALL sp_validate_objects();
DROP PROCEDURE sp_validate_objects;
SELECT 'Object validation passed' AS Result;
